import pandas as pd, numpy as np
# gather all files with do_CarbonFiltration
files = {8:experiment_8_csv,9:experiment_9_csv,10:experiment_10_csv}
# Also earlier experiments may have carbon values
allf = [experiment_1_csv,experiment_2_csv,experiment_3_csv,experiment_4_csv,
        experiment_6_csv,experiment_7_csv,experiment_8_csv,experiment_9_csv,experiment_10_csv]
rows=[]
for f in allf:
    try:
        d=pd.read_csv(f)
        if 'do_CarbonFiltration' in d.columns:
            for cv,g in d.groupby('do_CarbonFiltration'):
                rows.append((cv,g['HarvestBiomass'].mean(),len(g)))
    except Exception as e:
        pass
r=pd.DataFrame(rows,columns=['carbon','biomass','n']).groupby('carbon').agg({'biomass':'mean','n':'sum'})
print(r)

